1 | import React, { useSyncExternalStore } from 'react';
2 | import type { TaskItem } from '../../../src/types.js';
3 | import { TaskManagerStore, selectFilteredTasks, type TaskManagerState } from './store.js';
4 | 
5 | export interface ReactTaskManagerProps {
6 |   store: TaskManagerStore;
7 | }
8 | 
9 | /**
10 |  * Real React view over a synchronous store.
11 |  *
12 |  * Rendering goes through React (reconciliation, hooks, event handlers); the state
13 |  * itself lives in `TaskManagerStore` so a test/agent adapter can read it
14 |  * deterministically right after dispatching an action.
15 |  */
16 | export const ReactTaskManager: React.FC<ReactTaskManagerProps> = ({ store }) => {
17 |   const state: TaskManagerState = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);
18 |   const visible: TaskItem[] = selectFilteredTasks(state);
19 | 
20 |   return (
21 |     <div className="task-manager" data-agent-id="task-manager:root">
22 |       <header>
23 |         <h1>Task Manager (React)</h1>
24 |         <span data-agent-id="task-manager:count">Total: {state.tasks.length}</span>
25 |       </header>
26 | 
27 |       {state.errorMessage && (
28 |         <div role="alert" className="error-banner" data-agent-id="task-manager:error-banner">
29 |           <span>{state.errorMessage}</span>
30 |           <button
31 |             data-agent-id="task-manager:retry-btn"
32 |             data-testid="retry-btn"
33 |             onClick={() => {
34 |               void store.retrySave().catch(() => undefined);
35 |             }}
36 |           >
37 |             Retry
38 |           </button>
39 |         </div>
40 |       )}
41 | 
42 |       {state.successMessage && (
43 |         <div className="success-banner" data-agent-id="task-manager:success-banner">
44 |           {state.successMessage}
45 |         </div>
46 |       )}
47 | 
48 |       <section className="controls">
49 |         <input
50 |           type="text"
51 |           placeholder="Search tasks or tags..."
52 |           value={state.searchQuery}
53 |           onChange={(e) => store.setSearchQuery(e.target.value)}
54 |           data-agent-id="task-manager:search"
55 |           data-testid="search-input"
56 |         />
57 | 
58 |         <select
59 |           value={state.filterStatus}
60 |           onChange={(e) => store.setFilterStatus(e.target.value)}
61 |           data-agent-id="task-manager:status-filter"
62 |           data-testid="status-filter"
63 |         >
64 |           <option value="All">All Status</option>
65 |           <option value="Active">Active</option>
66 |           <option value="Completed">Completed</option>
67 |         </select>
68 | 
69 |         <select
70 |           value={state.filterPriority}
71 |           onChange={(e) => store.setFilterPriority(e.target.value)}
72 |           data-agent-id="task-manager:priority-filter"
73 |         >
74 |           <option value="All">All Priorities</option>
75 |           <option value="High">High</option>
76 |           <option value="Medium">Medium</option>
77 |           <option value="Low">Low</option>
78 |         </select>
79 | 
80 |         <button
81 |           disabled={state.isSaving}
82 |           onClick={() => {
83 |             void store.saveTasks().catch(() => undefined);
84 |           }}
85 |           data-agent-id="task-manager:save-btn"
86 |           data-testid="save-btn"
87 |         >
88 |           {state.isSaving ? 'Saving...' : 'Save Tasks'}
89 |         </button>
90 |       </section>
91 | 
92 |       <ul className="task-list" data-agent-id="task-manager:list">
93 |         {visible.map((task) => (
94 |           <li
95 |             key={task.id}
96 |             className={`task-item ${task.status.toLowerCase()}`}
97 |             data-agent-id={`task-item:${task.id}`}
98 |           >
99 |             <input
100 |               type="checkbox"
101 |               checked={task.status === 'Completed'}
102 |               onChange={() => store.toggleTask(task.id)}
103 |             />
104 |             <span className="title">{task.title}</span>
105 |             <span className={`badge ${task.priority.toLowerCase()}`}>{task.priority}</span>
106 |             <div className="tags">
107 |               {task.tags?.map((tag) => (
108 |                 <span key={tag} className="tag">
109 |                   #{tag}
110 |                 </span>
111 |               ))}
112 |             </div>
113 |           </li>
114 |         ))}
115 |       </ul>
116 |     </div>
117 |   );
118 | };
119 |

